<?php
namespace App\Domain\AI\Knowledge\Models;use App\Domain\AI\Agents\Data\AuthorizedAiLifecycleActor;use App\Domain\AI\Knowledge\Enums\{KnowledgeSourceStatus,KnowledgeSourceType};use App\Domain\AI\Tenancy\AiTenantModel;use App\Models\User;use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};use Illuminate\Support\Str;
final class KnowledgeSource extends AiTenantModel{protected$table='ai_knowledge_sources';protected$guarded=['*'];protected$casts=['type'=>KnowledgeSourceType::class,'status'=>KnowledgeSourceStatus::class,'archived_at'=>'datetime'];public function getRouteKeyName():string{return'uuid';}public function isAiAppendOnly():bool{return true;}protected function immutableIdentityAttributes():array{return['uuid','name','type','status','created_by_user_id','archived_at','archived_by_user_id'];}protected static function booted():void{parent::booted();static::creating(fn(self$m)=>$m->uuid??=(string)Str::uuid());}public function versions():HasMany{return$this->hasMany(KnowledgeSourceVersion::class,'knowledge_source_id');}public function creator():BelongsTo{return$this->belongsTo(User::class,'created_by_user_id');}public function archive(AuthorizedAiLifecycleActor$a):void{$this->assertLifecycleActor($a);if($this->status!==KnowledgeSourceStatus::Active)throw new \DomainException('Knowledge source cannot be archived.');$this->persistNamedLifecycle(['status','archived_at','archived_by_user_id'],function()use($a){$this->status=KnowledgeSourceStatus::Archived;$this->archived_at=now();$this->archived_by_user_id=$a->actorUserId;});}}
